def distinctPrimeFactors(num) :
    primes = set()
    if (num == 2) :
        primes.add(num)
    sqrt = int(math.sqrt(num))
    for j in range(2, sqrt + 1) :
        if (num % j == 0) :
            primes.add(j)
            while (num % j == 0) :
                num //= j
    if (num > 2) :
        primes.add(num)
    return (primes)
