    one = []
    n = len(s)
    for i in range(n):
        if s[i] == '1':
            one.append(i)


    for i in range(n):
        curr = 0
        if s[i] == '0':
            start = bisect.bisect(one,i)
            if start < len(one):
                start = one[start]
            else:
                start = n
        else:
            start = i

        #print(i,start)
        for j in range(start,n):
            curr *= 2
            if s[j] == '1':
                curr += 1
            #print(curr,i,j-i+1,j)
